/**
 * AppFlowy API bridge for generated code records.
 *
 * This module is endpoint-agnostic: you can point it at your own
 * AppFlowy gateway endpoints via environment variables.
 */

const DEFAULT_TIMEOUT_MS = 30000;

function toIsoDate() {
  return new Date().toISOString().slice(0, 10);
}

function slugify(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || "feature";
}

function withTimeout(ms = DEFAULT_TIMEOUT_MS) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  return { controller, timer };
}

class AppFlowyCodeBridge {
  constructor(options = {}) {
    this.baseUrl = (options.baseUrl || process.env.APPFLOWY_API_URL || "").replace(/\/$/, "");
    this.apiKey = options.apiKey || process.env.APPFLOWY_API_KEY || "";
    this.database = options.database || process.env.APPFLOWY_DATABASE_ID || "code_snippets";
    this.searchEndpoint = options.searchEndpoint || process.env.APPFLOWY_SEARCH_ENDPOINT || "/api/code/search";
    this.createEndpoint = options.createEndpoint || process.env.APPFLOWY_CREATE_ENDPOINT || "/api/code/create";
    this.updateEndpoint = options.updateEndpoint || process.env.APPFLOWY_UPDATE_ENDPOINT || "/api/code/update";
  }

  get enabled() {
    return Boolean(this.baseUrl && this.apiKey && this.database);
  }

  headers() {
    return {
      Authorization: `Bearer ${this.apiKey}`,
      "Content-Type": "application/json",
    };
  }

  async searchAppFlowy(query, { limit = 5 } = {}) {
    if (!this.enabled) return [];

    const payload = {
      database: this.database,
      query,
      limit,
      category: "Code",
    };

    const { controller, timer } = withTimeout();
    try {
      const response = await fetch(`${this.baseUrl}${this.searchEndpoint}`, {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(payload),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`AppFlowy search failed: ${response.status}`);
      }

      const data = await response.json();
      if (Array.isArray(data)) return data;
      if (Array.isArray(data.records)) return data.records;
      if (Array.isArray(data.list)) return data.list;
      return [];
    } finally {
      clearTimeout(timer);
    }
  }

  buildMarkdownTemplate({
    featureName,
    language,
    description,
    installation,
    usage,
    fullCode,
    dependencies = [],
    integrationPoints = [],
    date = toIsoDate(),
  }) {
    const depLines = dependencies.length ? dependencies.map((dep) => `- ${dep}`).join("\n") : "- none";
    const integrationLines = integrationPoints.length
      ? integrationPoints.map((item) => `- ${item}`).join("\n")
      : "- none";

    return `# ${featureName}
**Status:** Generated by CoderAgent
**Date:** ${date}
**Language:** ${language}

## Description
${description}

## Installation
\`\`\`bash
${installation}
\`\`\`

## Usage
\`\`\`${language}
${usage}
\`\`\`

## Full Code
\`\`\`${language}
${fullCode}
\`\`\`

## Dependencies
${depLines}

## Integration Points
${integrationLines}

---
Status: Ready to Review
Tagged: #generated #code #${slugify(featureName)}
`;
  }

  async saveGeneratedCode({
    featureName,
    language,
    markdown,
    dependencies = [],
    linkedAgent = "CoderAgent",
    fileLink = "",
  }) {
    if (!this.enabled) {
      return {
        status: "skipped",
        reason: "AppFlowy not configured",
      };
    }

    const payload = {
      database: this.database,
      title: featureName,
      content: markdown,
      language,
      status: "Ready to Review",
      generatedBy: "CoderAgent",
      linkedAgent,
      dependencies: dependencies.join(", "),
      category: "Code",
      tags: ["generated", "code", slugify(featureName)],
      fileLink,
      createdDate: new Date().toISOString(),
    };

    const { controller, timer } = withTimeout();
    try {
      const response = await fetch(`${this.baseUrl}${this.createEndpoint}`, {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(payload),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`AppFlowy create failed: ${response.status}`);
      }

      const data = await response.json();
      return {
        status: "Ready to Review",
        recordId: data.id || data.record_id || null,
        recordLink: data.url || data.record_link || null,
        tags: payload.tags.map((tag) => `#${tag}`),
        raw: data,
      };
    } finally {
      clearTimeout(timer);
    }
  }

  async updateStatus(recordId, status, extra = {}) {
    if (!this.enabled) {
      return { status: "skipped", reason: "AppFlowy not configured" };
    }

    const payload = {
      database: this.database,
      recordId,
      status,
      ...extra,
    };

    const { controller, timer } = withTimeout();
    try {
      const response = await fetch(`${this.baseUrl}${this.updateEndpoint}`, {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(payload),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`AppFlowy update failed: ${response.status}`);
      }

      return await response.json();
    } finally {
      clearTimeout(timer);
    }
  }
}

module.exports = {
  AppFlowyCodeBridge,
  slugify,
};
